44	bool initializeNormalRopeCosSinCacheHost(
45	    rt::Tensor& cosSinCache, RopeConfig const& config, cudaStream_t stream) noexcept
46	{
47	    int64_t const maxLength = cosSinCache.getShape()[1];
48	    int64_t const rotaryDim = cosSinCache.getShape()[2];
49	    if (rotaryDim <= 0 || rotaryDim % 2 != 0)
50	    {
51	        LOG_ERROR("Normal RoPE CosSinCache requires a positive, even rotaryDim; got %lld.",
52	            static_cast<long long>(rotaryDim));
53	        return false;
54	    }
55	
56	    int64_t const halfDim = rotaryDim / 2;
57	    int64_t const rotatedAngles = static_cast<int64_t>(
58	        std::floor(std::clamp(config.partialRotaryFactor, 0.0F, 1.0F) * static_cast<float>(halfDim)));
59	    std::vector<float> hostBuf(static_cast<size_t>(maxLength * rotaryDim));
60	    for (int64_t pos = 0; pos < maxLength; ++pos)
61	    {
62	        for (int64_t d = 0; d < halfDim; ++d)
63	        {
64	            size_t const cosOffset = static_cast<size_t>(pos * rotaryDim + d);
65	            if (config.type == RopeType::kProportional && d >= rotatedAngles)
66	            {
67	                hostBuf[cosOffset] = 1.0F;
68	                hostBuf[cosOffset + static_cast<size_t>(halfDim)] = 0.0F;
69	            }
70	            else
71	            {
72	                float const ropeConstant
73	                    = std::pow(config.rotaryTheta, 2.0F * static_cast<float>(d) / static_cast<float>(rotaryDim));
74	                float const invFreq = static_cast<float>(pos) * config.rotaryScale / ropeConstant;
75	                hostBuf[cosOffset] = std::cos(invFreq);
76	                hostBuf[cosOffset + static_cast<size_t>(halfDim)] = std::sin(invFreq);
77	            }
78	        }
79	    }
80	
81	    try
82	    {
83	        CUDA_CHECK(cudaMemcpyAsync(cosSinCache.dataPointer<float>(), hostBuf.data(), hostBuf.size() * sizeof(float),
84	            cudaMemcpyHostToDevice, stream));
85	        CUDA_CHECK(cudaStreamSynchronize(stream));
86	    }
87	    catch (std::exception const& e)
88	    {
89	        LOG_ERROR("cudaMemcpyAsync for initializeNormalRopeCosSinCacheHost failed: %s", e.what());
90	        return false;
91	    }
92	    return true;
93	}
