95	bool canUseOptimizedNormalRopeKernel(RopeConfig const& config, int64_t rotaryDim)
96	{
97	    if (config.type == RopeType::kProportional)
98	    {
99	        return false;
100	    }
101	
102	    // The optimized CUDA initializer is instantiated only for the rotary
103	    // dimensions listed here. Each specialization processes the table in a
104	    // 64-element rotary-dimension granularity; other valid RoPE dimensions use
105	    // the generic host initializer below.
106	    switch (rotaryDim)
107	    {
108	    case 64:
109	    case 128: return true;
110	    default: return false;
111	    }
112	}
