144	RopeConfig collectRopeConfig(nlohmann::json const& config)
145	{
146	    RopeConfig ropeConfig{};
147	
148	    // Check for explicit use_rope flag (set by hybrid model export)
149	    if (config.contains("use_rope") && config["use_rope"].is_boolean() && !config["use_rope"].get<bool>())
150	    {
151	        ropeConfig.type = RopeType::kNoRope;
152	        if (config.contains("max_position_embeddings"))
153	        {
154	            ropeConfig.maxPositionEmbeddings = config["max_position_embeddings"].get<int32_t>();
155	        }
156	        LOG_INFO("Collected rope config: %s", formatRopeConfig(ropeConfig).c_str());
157	        return ropeConfig;
158	    }
159	
160	    auto ropeScalingIt = config.find("rope_scaling");
161	    if (ropeScalingIt != config.end())
162	    {
163	        auto ropeTypeIt = ropeScalingIt->find("type");
164	        if (ropeTypeIt == ropeScalingIt->end())
165	        {
166	            ropeTypeIt = ropeScalingIt->find("rope_type");
167	        }
168	        auto mropeSectionIt = ropeScalingIt->find("mrope_section");
169	        if (ropeTypeIt != ropeScalingIt->end())
170	        {
171	            std::string const ropeTypeStr = ropeTypeIt->get<std::string>();
172	            if (ropeTypeStr == "mrope" || (ropeTypeStr == "default" && mropeSectionIt != ropeScalingIt->end()))
173	            {
174	                // Accept both the legacy HF value ("mrope") and the newer
175	                // `Qwen2_5_VLVisionConfig` convention ("default" + mrope_section).
176	                // Talker uses same config (3D position_ids + interleaved MRoPE) as in PyTorch.
177	                ropeConfig.type = RopeType::kMRope;
178	            }
179	            else if (ropeTypeStr == "default" || ropeTypeStr == "llama3")
180	            {
181	                // Route the llama3 config to default type.
182	                ropeConfig.type = RopeType::kDefault;
183	            }
184	            else if (ropeTypeStr == "proportional")
185	            {
186	                ropeConfig.type = RopeType::kProportional;
187	            }
188	            else if (ropeTypeStr == "dynamic")
189	            {
190	                ropeConfig.type = RopeType::kDynamic;
191	            }
192	            else if (ropeTypeStr == "longrope")
193	            {
194	                ropeConfig.type = RopeType::kLongRope;
195	            }
196	        }
197	
198	        // Parse long rope scaling parameters when requested
199	        if (ropeConfig.type == RopeType::kLongRope)
200	        {
201	            LongRopeParams params{};
202	            auto longFactorIt = ropeScalingIt->find("long_factor");
203	            check::check((longFactorIt != ropeScalingIt->end() && longFactorIt->is_array()),
204	                "rope_scaling.long_factor must be a non-empty array for longrope");
205	            params.longFactor = longFactorIt->get<std::vector<float>>();
206	
207	            auto shortFactorIt = ropeScalingIt->find("short_factor");
208	            check::check((shortFactorIt != ropeScalingIt->end() && shortFactorIt->is_array()),
209	                "rope_scaling.short_factor must be a non-empty array for longrope");
210	            params.shortFactor = shortFactorIt->get<std::vector<float>>();
211	
212	            check::check(params.longFactor.size() == params.shortFactor.size(),
213	                "rope_scaling.long_factor size differs from short_factor size");
214	
215	            check::check(config.contains("original_max_position_embeddings"),
216	                "original_max_position_embeddings is not specified in the model config");
217	            params.originalMaxPositionEmbeddings = config["original_max_position_embeddings"].get<int32_t>();
218	
219	            ropeConfig.longRope = std::move(params);
220	        }
221	
222	        if (ropeConfig.type == RopeType::kProportional)
223	        {
224	            auto partialIt = ropeScalingIt->find("partial_rotary_factor");
225	            if (partialIt != ropeScalingIt->end())
226	            {
227	                ropeConfig.partialRotaryFactor = partialIt->get<float>();
228	            }
229	            else if (config.contains("partial_rotary_factor"))
230	            {
231	                ropeConfig.partialRotaryFactor = config["partial_rotary_factor"].get<float>();
232	            }
233	
234	            auto factorIt = ropeScalingIt->find("factor");
235	            if (factorIt != ropeScalingIt->end())
236	            {
237	                float const factor = factorIt->get<float>();
238	                check::check(factor > 0.0F, "rope_scaling.factor must be positive for proportional RoPE");
239	                ropeConfig.rotaryScale = 1.0F / factor;
240	            }
241	        }
242	    }
243	    else
244	    {
245	        LOG_WARNING(
246	            "rope_scaling is not specified in the model config, using default rope type. This could misalign with the "
247	            "model configuration, please check the config file to ensure the correctness");
248	        ropeConfig.type = RopeType::kDefault;
249	    }
250	
251	    // Detect RopeTheta
252	    if (config.contains("rope_theta"))
253	    {
254	        ropeConfig.rotaryTheta = config["rope_theta"].get<float>();
255	    }
256	    else
257	    {
258	        LOG_WARNING("rope_theta is not specified in the model config, using default value: %f", ropeConfig.rotaryTheta);
259	    }
260	
261	    // Detect MaxPositionEmbeddings
262	    if (config.contains("max_position_embeddings"))
263	    {
264	        ropeConfig.maxPositionEmbeddings = config["max_position_embeddings"].get<int32_t>();
265	    }
266	    else
267	    {
268	        LOG_WARNING("max_position_embeddings is not specified in the model config, using default value: %d",
269	            ropeConfig.maxPositionEmbeddings);
270	    }
271	
272	    LOG_INFO("Collected rope config: %s", formatRopeConfig(ropeConfig).c_str());
273	    return ropeConfig;
274	}
