276	bool initializeRopeCosSinCache(rt::Tensor& cosSinCache, RopeConfig const& config, cudaStream_t stream) noexcept
277	{
278	    if (config.type == RopeType::kMRope)
279	    {
280	        LOG_ERROR("MRope is context dependent rope type, which cannot be initialized with basic parameters.");
281	        return false;
282	    }
283	    else if (config.type == RopeType::kLongRope)
284	    {
285	        LOG_ERROR("Please use initializeLongRopeCosSinCache instead.");
286	        return false;
287	    }
288	
289	    // Tensor shape: [1, maxLength, rotaryDim]
290	    if (cosSinCache.getShape().getNumDims() != 3 || cosSinCache.getDataType() != DataType::kFLOAT)
291	    {
292	        LOG_ERROR("Persistent RopeCosSinCache should be float tensor with dimensions: [1, maxLength, rotaryDim].");
293	        return false;
294	    }
295	    int64_t ropeMaxLength = cosSinCache.getShape()[1];
296	    int64_t rotaryDim = cosSinCache.getShape()[2];
297	    if (config.type == RopeType::kDefault || config.type == RopeType::kDynamic
298	        || config.type == RopeType::kProportional)
299	    {
300	        if (config.type == RopeType::kDynamic && ropeMaxLength > config.maxPositionEmbeddings)
301	        {
302	            LOG_ERROR("Dynamic rope type with sequence length larger than maxPositionEmbeddings is not supported.");
303	            return false;
304	        }
305	        if (ropeMaxLength > config.maxPositionEmbeddings)
306	        {
307	            LOG_WARNING(
308	                "maxLength %d is greater than maxPositionEmbeddings %d indicated by model config, this could cause "
309	                "inaccurate generation results",
310	                ropeMaxLength, config.maxPositionEmbeddings);
311	        }
312	
313	        if (!canUseOptimizedNormalRopeKernel(config, rotaryDim))
314	        {
315	            LOG_INFO("Initializing normal RoPE cos/sin cache on host for rotaryDim=%lld.",
316	                static_cast<long long>(rotaryDim));
317	            return initializeNormalRopeCosSinCacheHost(cosSinCache, config, stream);
318	        }
319	
320	        try
321	        {
322	            kernel::initializeNormalRopeCosSin(cosSinCache.dataPointer<float>(), config.rotaryTheta, config.rotaryScale,
323	                config.partialRotaryFactor, rotaryDim, ropeMaxLength, stream);
324	        }
325	        catch (std::exception const& e)
326	        {
327	            LOG_ERROR("CUDA kernel launch for initializeNormalRopeCosSin failed: %s", e.what());
328	            return false;
329	        }
330	    }
331	    return true;
332	}
