334	bool initializeNopeCosSinCache(rt::Tensor& cosSinCache, cudaStream_t stream) noexcept
335	{
336	    if (cosSinCache.getShape().getNumDims() != 3 || cosSinCache.getDataType() != DataType::kFLOAT)
337	    {
338	        LOG_ERROR("NoRope CosSinCache should be float tensor with dimensions: [1, maxLength, rotaryDim].");
339	        return false;
340	    }
341	
342	    int64_t maxLength = cosSinCache.getShape()[1];
343	    int64_t rotaryDim = cosSinCache.getShape()[2];
344	    int64_t halfDim = rotaryDim / 2;
345	
346	    std::vector<float> hostBuf(static_cast<size_t>(maxLength * rotaryDim));
347	    for (int64_t pos = 0; pos < maxLength; ++pos)
348	    {
349	        for (int64_t d = 0; d < halfDim; ++d)
350	        {
351	            hostBuf[pos * rotaryDim + d] = 1.0F;
352	        }
353	        for (int64_t d = halfDim; d < rotaryDim; ++d)
354	        {
355	            hostBuf[pos * rotaryDim + d] = 0.0F;
356	        }
357	    }
358	
359	    try
360	    {
361	        CUDA_CHECK(cudaMemcpyAsync(cosSinCache.dataPointer<float>(), hostBuf.data(), hostBuf.size() * sizeof(float),
362	            cudaMemcpyHostToDevice, stream));
363	        CUDA_CHECK(cudaStreamSynchronize(stream));
364	    }
365	    catch (std::exception const& e)
366	    {
367	        LOG_ERROR("cudaMemcpyAsync for initializeNopeCosSinCache failed: %s", e.what());
368	        return false;
369	    }
370	    return true;
