373	bool initializeLongRopeCosSinCache(
374	    rt::Tensor& shortCosSinCache, rt::Tensor& longCosSinCache, RopeConfig const& config, cudaStream_t stream)
375	{
376	
377	    if (config.type != RopeType::kLongRope)
378	    {
379	        LOG_ERROR("This function is only used for initializing LongRope cos/sin cache.");
380	        return false;
381	    }
382	
383	    // Tensor shape: [1, maxLength, rotaryDim]
384	    if (shortCosSinCache.getShape().getNumDims() != 3 || shortCosSinCache.getDataType() != DataType::kFLOAT
385	        || longCosSinCache.getShape().getNumDims() != 3 || longCosSinCache.getDataType() != DataType::kFLOAT)
386	    {
387	        LOG_ERROR("Persistent RopeCosSinCache should be float tensor with dimensions: [1, maxLength, rotaryDim].");
388	        return false;
389	    }
390	
391	    int64_t ropeMaxLength = shortCosSinCache.getShape()[1];
392	    int64_t rotaryDim = shortCosSinCache.getShape()[2];
393	
394	    // Validate long/short factors before creating tensors and launching the kernel
395	    if (!config.longRope.has_value() || config.longRope->longFactor.empty() || config.longRope->shortFactor.empty())
396	    {
397	        LOG_ERROR("LongRope requires non-empty long_factor and short_factor arrays in rope_scaling.");
398	        return false;
399	    }
400	
401	    Coords shape{static_cast<int64_t>(config.longRope->longFactor.size())};
402	
403	    Tensor longFactorTensor(shape, DeviceType::kGPU, DataType::kFLOAT, "long_factor");
404	    Tensor shortFactorTensor(shape, DeviceType::kGPU, DataType::kFLOAT, "short_factor");
405	    CUDA_CHECK(cudaMemcpyAsync(longFactorTensor.rawPointer(), config.longRope->longFactor.data(),
406	        longFactorTensor.getMemoryCapacity(), cudaMemcpyHostToDevice, stream));
407	    CUDA_CHECK(cudaMemcpyAsync(shortFactorTensor.rawPointer(), config.longRope->shortFactor.data(),
408	        shortFactorTensor.getMemoryCapacity(), cudaMemcpyHostToDevice, stream));
409	    try
410	    {
411	        kernel::initializeLongRopeCosSin(shortCosSinCache.dataPointer<float>(), longCosSinCache.dataPointer<float>(),
412	            shortFactorTensor.dataPointer<float>(), longFactorTensor.dataPointer<float>(), config.rotaryTheta,
413	            rotaryDim, ropeMaxLength, config.maxPositionEmbeddings, config.longRope->originalMaxPositionEmbeddings,
414	            stream);
415	    }
416	    catch (std::exception const& e)
417	    {
418	        LOG_ERROR("CUDA kernel launch for initializeLongRopeCosSin failed: %s", e.what());
419	        return false;
420	    }
421	    return true;
422	}
