424	//=============================================================================
425	// CPU Vector Compaction Utility for Batch Eviction
426	//=============================================================================
427	
428	template <typename T>
429	void compactVector(std::vector<int32_t> const& batchMapping, std::vector<T>& vec)
430	{
431	    // Validate that vector size matches batchMapping size
432	    // In batch eviction, batchMapping[i] indicates where batch i should move to
433	    ELLM_CHECK(vec.size() == batchMapping.size(),
434	        format::fmtstr("compactVector: vector size (%zu) does not match batchMapping size (%zu)", vec.size(),
435	            batchMapping.size()));
436	
437	    std::vector<T> compacted;
438	    compacted.reserve(vec.size());
439	
440	    for (size_t i = 0; i < vec.size(); ++i)
441	    {
442	        if (batchMapping[i] >= 0)
443	        {
444	            compacted.push_back(std::move(vec[i]));
445	        }
446	    }
447	
448	    vec = std::move(compacted);
449	}
450	
451	template void compactVector<int8_t>(std::vector<int32_t> const&, std::vector<int8_t>&);
452	template void compactVector<int32_t>(std::vector<int32_t> const&, std::vector<int32_t>&);
453	template void compactVector<std::vector<int32_t>>(std::vector<int32_t> const&, std::vector<std::vector<int32_t>>&);
454	template void compactVector<std::string>(std::vector<int32_t> const&, std::vector<std::string>&);
455	template void compactVector<std::vector<std::string>>(
456	    std::vector<int32_t> const&, std::vector<std::vector<std::string>>&);
457	template void compactVector<std::unordered_map<int32_t, float>>(
458	    std::vector<int32_t> const&, std::vector<std::unordered_map<int32_t, float>>&);
459	template void compactVector<SlotStreamState>(std::vector<int32_t> const&, std::vector<SlotStreamState>&);
460	template void compactVector<LogprobsSlot>(std::vector<int32_t> const&, std::vector<LogprobsSlot>&);
461	
462	// Build batch mapping from finished states
463	// Returns a vector mapping old batch indices to new indices (-1 for evicted batches)
464	std::vector<int32_t> buildBatchMapping(std::vector<int8_t> const& finishedStates)
465	{
466	    int32_t const oldActiveBatch = static_cast<int32_t>(finishedStates.size());
467	    std::vector<int32_t> mapping(oldActiveBatch);
468	
469	    int32_t newIdx = 0;
470	    for (int32_t oldIdx = 0; oldIdx < oldActiveBatch; ++oldIdx)
471	    {
472	        if (!finishedStates[oldIdx])
473	        {
474	            mapping[oldIdx] = newIdx;
475	            newIdx++;
476	        }
477	        else
478	        {
479	            mapping[oldIdx] = -1; // Mark for eviction
480	        }
481	    }
482	
483	    return mapping;
484	}
