488	//=============================================================================
489	
490	EmbeddingData loadEmbeddingTable(std::filesystem::path const& embeddingPath, cudaStream_t stream)
491	{
492	    ELLM_CHECK(std::filesystem::exists(embeddingPath),
493	        format::fmtstr("Embedding file not found: %s", embeddingPath.string().c_str()));
494	
495	    std::vector<rt::Tensor> tensors;
496	    ELLM_CHECK(safetensors::loadSafetensors(embeddingPath, tensors, stream),
497	        format::fmtstr("Failed to load embedding file: %s", embeddingPath.string().c_str()));
498	
499	    // Find tensors by name
500	    rt::Tensor* embeddingPtr = nullptr;
501	    rt::Tensor* scalesPtr = nullptr;
502	
503	    for (auto& tensor : tensors)
504	    {
505	        if (tensor.getName() == "embedding")
506	        {
507	            embeddingPtr = &tensor;
508	        }
509	        else if (tensor.getName() == "embedding_scale")
510	        {
511	            scalesPtr = &tensor;
512	        }
513	    }
514	
515	    ELLM_CHECK(embeddingPtr != nullptr,
516	        format::fmtstr("Embedding file missing 'embedding' tensor: %s", embeddingPath.string().c_str()));
517	
518	    ELLM_CHECK(embeddingPtr->getShape().getNumDims() == 2,
519	        format::fmtstr("Embedding tensor must be 2D, got %d dimensions", embeddingPtr->getShape().getNumDims()));
520	
521	    int64_t vocabSize = embeddingPtr->getShape()[0];
522	    int64_t hiddenSize = embeddingPtr->getShape()[1];
523	
524	    EmbeddingData result;
525	
526	    // Detect FP8 vs FP16 by checking dtype
527	    if (embeddingPtr->getDataType() == nvinfer1::DataType::kFP8)
528	    {
529	        // FP8 format - requires scales
530	        ELLM_CHECK(scalesPtr != nullptr,
531	            format::fmtstr("FP8 embedding requires 'embedding_scale' tensor: %s", embeddingPath.string().c_str()));
532	
533	        ELLM_CHECK(scalesPtr->getDataType() == nvinfer1::DataType::kFLOAT,
534	            format::fmtstr("embedding_scale must have FP32 dtype, got %d", static_cast<int>(scalesPtr->getDataType())));
535	
536	        ELLM_CHECK(scalesPtr->getShape().getNumDims() == 2,
537	            format::fmtstr("embedding_scale must be 2D, got %d dimensions", scalesPtr->getShape().getNumDims()));
538	
539	        int64_t scaleVocabSize = scalesPtr->getShape()[0];
540	        int64_t numGroups = scalesPtr->getShape()[1];
541	
542	        ELLM_CHECK(vocabSize == scaleVocabSize,
543	            format::fmtstr("Vocab size mismatch: embedding has %ld, scales has %ld", vocabSize, scaleVocabSize));
544	
545	        ELLM_CHECK(hiddenSize % kFP8EmbeddingBlockSize == 0,
546	            format::fmtstr("Hidden size %ld must be divisible by block size %ld", hiddenSize, kFP8EmbeddingBlockSize));
547	
548	        int64_t expectedNumGroups = hiddenSize / kFP8EmbeddingBlockSize;
549	        ELLM_CHECK(numGroups == expectedNumGroups,
550	            format::fmtstr("Scale groups mismatch: expected %ld, got %ld", expectedNumGroups, numGroups));
551	
552	        LOG_INFO(
553	            "Loaded FP8 embedding: [%ld, %ld], scales: [%ld, %ld]", vocabSize, hiddenSize, scaleVocabSize, numGroups);
554	
555	        result.table = std::move(*embeddingPtr);
556	        result.tableScalingFactor = std::move(*scalesPtr);
557	    }
558	    else
559	    {
560	        // FP16 format
561	        LOG_INFO("Loaded FP16 embedding: [%ld, %ld]", vocabSize, hiddenSize);
562	
563	        result.table = std::move(*embeddingPtr);
564	    }
565	
566	    return result;
567	}
568	
569	int32_t clampMaxGenerateLengthForKVCapacity(std::vector<int32_t> const& effectivePrefillLengths,
570	    int32_t requestedMaxGenerateLength, int32_t kvCacheCapacity, int32_t kvCacheReserveLength)
571	{
572	    check::check(!effectivePrefillLengths.empty(), "effectivePrefillLengths must not be empty");
573	
574	    int32_t clampedMaxGenerateLength = requestedMaxGenerateLength;
575	    for (int32_t const prefillLength : effectivePrefillLengths)
576	    {
577	        int32_t const availableGenerateLength = std::max(0, kvCacheCapacity - prefillLength - kvCacheReserveLength);
578	        clampedMaxGenerateLength = std::min(clampedMaxGenerateLength, availableGenerateLength);
579	    }
580	
581	    return clampedMaxGenerateLength;
582	}
583	
584	rt::Tensor generateMultimodalIndices(rt::Tensor const& inputIds, std::optional<int32_t> audioTokenId,
585	    std::optional<int32_t> imageTokenId, int32_t vocabSize)
586	{
587	    auto const shape = inputIds.getShape();
588	    check::check(shape.getNumDims() == 2, "inputIds must be 2D tensor");
589	    int64_t const batchSize = shape[0];
590	    int64_t const seqLen = shape[1];
591	
592	    rt::Tensor multimodalIndices({batchSize, seqLen}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32);
593	
594	    int32_t const* inputIdsPtr = inputIds.dataPointer<int32_t>();
595	    int32_t* indicesPtr = multimodalIndices.dataPointer<int32_t>();
596	
597	    int32_t audioIndex = 0;
598	    int32_t imageIndex = 0;
599	
600	    for (int64_t b = 0; b < batchSize; ++b)
601	    {
602	        for (int64_t s = 0; s < seqLen; ++s)
603	        {
604	            int64_t const pos = b * seqLen + s;
605	            int32_t const tokenId = inputIdsPtr[pos];
606	
607	            if (audioTokenId.has_value() && tokenId == *audioTokenId)
608	            {
609	                indicesPtr[pos] = audioIndex++;
610	            }
611	            else if ((imageTokenId.has_value() && tokenId == *imageTokenId) || tokenId >= vocabSize)
612	            {
613	                indicesPtr[pos] = imageIndex++;
614	            }
615	            else
616	            {
617	                indicesPtr[pos] = 0;
618	            }
619	        }
620	    }
621	
622	    return multimodalIndices;
623	}
624	
625	rt::Tensor generateVisionBlockIds(rt::Tensor const& inputIds, int32_t imageTokenId)
626	{
627	    auto const shape = inputIds.getShape();
628	    check::check(shape.getNumDims() == 2, "inputIds must be 2D tensor");
629	    check::check(inputIds.getDeviceType() == rt::DeviceType::kCPU, "inputIds must be a host tensor");
630	    check::check(inputIds.getDataType() == nvinfer1::DataType::kINT32, "inputIds must have INT32 dtype");
631	    check::check(imageTokenId >= 0, "imageTokenId must be non-negative");
632	
633	    int64_t const batchSize = shape[0];
634	    int64_t const seqLen = shape[1];
635	    rt::Tensor blockIds({batchSize, seqLen}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32);
636	    int32_t const* tokens = inputIds.dataPointer<int32_t>();
637	    int32_t* blocks = blockIds.dataPointer<int32_t>();
638	
639	    for (int64_t b = 0; b < batchSize; ++b)
640	    {
641	        bool previousWasVision = false;
642	        int32_t nextBlockId = 0;
643	        int32_t currentBlockId = -1;
644	        for (int64_t s = 0; s < seqLen; ++s)
645	        {
646	            int64_t const offset = b * seqLen + s;
647	            int32_t const token = tokens[offset];
648	            bool const isVision = token == imageTokenId;
649	            if (isVision)
650	            {
651	                if (!previousWasVision)
652	                {
653	                    currentBlockId = nextBlockId++;
654	                }
655	                blocks[offset] = currentBlockId;
656	            }
657	            else
658	            {
659	                blocks[offset] = -1;
660	            }
661	            previousWasVision = isVision;
662	        }
663	    }
664	    return blockIds;
665	}
